#![cfg(unix)]
//! Offline real Session/queue/log fixtures. The one Transport uses loopback
//! configuration. The final-guard fixture invokes place but proves that no socket send occurs.
use moloch_live_runtime::{authority,dispatch,feedback,package_dispatch};
#[path="../src/collateral_feedback.rs"]mod collateral_feedback;
use collateral_feedback::{Boundary,RetainedReceipt,ReceiptStore};
#[path="../src/capital_allocation.rs"]mod capital_allocation;
use capital_allocation::*;
use baal_transport_service::{Receipt,Scope,Config,Transport,DisabledCredentials,SystemClock,ReadOnlyAuthority,admission::AccountAdmission};
use moloch_replay::session::{Session,ExclusiveLock,atomic_json};
use serde_json::{Value,json};
use std::{fs,path::{Path,PathBuf}};
const T:&str="11111111-1111-4111-8111-111111111111";
const P:&str="22222222-2222-4222-8222-222222222222";
fn iso(n:i64)->String{chrono::DateTime::from_timestamp_millis(1_792_022_400_000+n).unwrap().to_rfc3339_opts(chrono::SecondsFormat::Millis,true)}
fn r(endpoint:String,data:Value,start:i64,end:i64)->Receipt{Receipt{endpoint,status:200,request_started_at:iso(start),received_at:iso(end),data}}
fn snapshot(cash:Value,debt:Value,available:Value,power:Value,at:i64)->(Receipt,Receipt){
 let rows:Vec<_>=[101,102].iter().map(|ex|json!({"profileId":P,"tournamentId":T,"componentId":format!("own-{ex}"),"coveredExchangeIds":[ex],"relationshipIds":[],"outstandingAdvance":if debt==json!(0.4){json!(0.2)}else{json!(0)},"guaranteedPayoutFloor":1,"diagnostic":null})).collect();
 (r(format!("/account?tournamentId={T}"),json!({"id":P,"balance":cash,"availableAdvance":available,"buyingPower":power}),at,at+1),r(format!("/portfolio/collateral?tournamentId={T}"),json!({"availableAdvance":available,"data":rows}),at+2,at+3))
}
fn retain(root:&Path,receipt:&Receipt)->RetainedReceipt{fs::create_dir_all(root.join("receipts")).unwrap();atomic_json(&root.join("receipts").join(format!("{}.json",feedback::digest(receipt).unwrap())),&serde_json::to_value(receipt).unwrap()).unwrap();RetainedReceipt::open(root,receipt,ReceiptStore::Ordinary).unwrap()}
macro_rules! boundary {($f:expr)=>{Boundary{root:&$f.root,owner_lock_path:&$f.owner_path,owner_lease:&$f.lease,transport:&$f.transport,ordinary:&$f.ordinary,packages:&$f.packages}};}
struct F{root:PathBuf,owner_path:PathBuf,lease:ExclusiveLock,transport:Transport,ordinary:dispatch::DispatchLog,packages:package_dispatch::PackageDispatchLog,bank:Session,policy:Value,seed:Value}
impl Drop for F{fn drop(&mut self){let _=fs::remove_dir_all(&self.root);}}
impl F{
 fn new()->Self{Self::with_unknown(false)}
 fn with_unknown(unknown:bool)->Self{
  let root=std::env::temp_dir().join(format!("collateral-feedback-{}-{}",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()));fs::create_dir_all(&root).unwrap();
  let owner_path=root.join("owner.lock");let lease=ExclusiveLock::acquire(&owner_path).unwrap();let scope=Scope{tournament_id:T.into(),tournament_slug:"cup".into(),exchanges:[("101".into(),"101".into()),("102".into(),"102".into()),("103".into(),"103".into())].into()};
  if unknown{let mut queue=AccountAdmission::open(&root.join("account-queue"),"fixture-account","prior-owner").unwrap();let c=json!({"op":"admit","scope":"fixture-account","now":100,"request":"unrelated","write":true,"binding":{"intent":"unrelated-intent","key":"unrelated-key","payload_hash":"a".repeat(64)},"authorized":true,"lease_valid":true,"permit_valid":true});assert_eq!(queue.command(c).unwrap()["admitted"],true);}
  if !unknown{let mut queue=AccountAdmission::open(&root.join("account-queue"),"fixture-account","original-fixture-clock").unwrap();queue.command(json!({"op":"status","scope":"fixture-account","now":1000})).unwrap();}
  let transport=Transport::new_for_mock(Config{queue_dir:root.join("account-queue"),account_scope:"fixture-account".into(),scope,maximum_pages:20,writes_enabled:false},Box::new(DisabledCredentials),Box::new(SystemClock),Box::new(ReadOnlyAuthority),"http://127.0.0.1:1/api/v1".into()).unwrap();
  let ordinary=dispatch::DispatchLog::open(&root.join("dispatch.ndjson")).unwrap();let packages=package_dispatch::PackageDispatchLog::open(&root.join("package-dispatch")).unwrap();let policy=json!({"initialCash":"40000.000000","maximumCommitted":"40000.000000","maximumMarketCost":"10000.000000","quantity":2,"maximumMarkets":3,"entryStopAt":iso(100000)});let seed=json!({"runId":"capital-fixture","availableCash":"70850.430000","accountSnapshotHash":"a".repeat(64),"observedAt":iso(0)});let mut bank=Session::open_live(&root.join("bank"),&policy,&seed).unwrap();
  for(i,ex)in ["101","102"].iter().enumerate(){let at=iso(i as i64*2500);bank.accept("books",i as u64+1,&json!({"type":"book","receivedAt":at,"book":{"tournamentId":T,"marketId":ex,"exchangeId":ex,"sequence":"1","sourceAt":at,"requestStartedAt":at,"receivedAt":at,"bids":[{"price":"0.400000","quantity":100}],"asks":[{"price":"0.450000","quantity":100}]}})).unwrap();}
  Self{root,owner_path,lease,transport,ordinary,packages,bank,policy,seed}
 }

 fn mandate(&self)->ApprovedMandate{let input=MandateInput{authorization_id:"human_moloch_additional_cash_20261016".into(),allocation_id:"owner-allocation-1".into(),control_sha256:"b".repeat(64),bank_manifest_hash:self.bank.manifest_hash().as_str().unwrap().into(),run_id:"capital-fixture".into(),account_scope:"fixture-account".into(),tournament_id:T.into(),tournament_slug:"cup".into(),profile_id:P.into(),scope_sha256:hash(&self.transport.scope()),delta:"10000.000000".into(),maximum_extra:"55579.915000".into(),maximum_effective_initial:"95579.915000".into(),maximum_committed:"95579.915000".into(),approved_at:iso(0),valid_until:iso(20000)};let approved=hash(&serde_json::to_value(&input).unwrap());ApprovedMandate::verify(input,&approved).unwrap()}
 fn sources(&self)->[RetainedReceipt;4]{let(a,c)=snapshot(json!(70850.43),json!(0),json!(0),json!(70850.43),2800);let p=r("/tournaments/cup/portfolio/positions".into(),json!({"positions":[],"summary":{"totalMarketValue":0,"totalCostBasis":0,"totalUnrealizedPnl":0}}),2804,2805);let o=r(format!("/orders?status=open&limit=200&tournamentId={T}"),json!({"data":[],"coverage":{"complete":true},"pagination":{"limit":200,"hasMore":false,"nextCursor":null}}),2806,2807);[retain(&self.root,&a),retain(&self.root,&c),retain(&self.root,&p),retain(&self.root,&o)]}
}
fn hash<T:serde::Serialize>(v:&T)->String{use sha2::{Digest,Sha256};format!("{:x}",Sha256::digest(serde_json::to_vec(v).unwrap()))}
fn sources(a:&[RetainedReceipt;4])->Sources<'_>{Sources{account:&a[0],collateral:&a[1],positions:&a[2],orders:&a[3]}}
#[test]fn genuine_original_sole_worker_sources_allocate_cash_without_profit_and_restart(){let mut f=F::new();let a=f.sources();let mandate=f.mandate();let before=f.bank.engine().report().unwrap();let orders=f.bank.engine().order_records();let expected=authority::reconciled_expected_cash(&f.bank).unwrap();let manifest=fs::read(f.root.join("bank/manifest.json")).unwrap();let b=boundary!(f);let tx=prepare(&f.bank,&b,&mandate,sources(&a),&iso(3000)).unwrap();let result=tx.commit(&mut f.bank,&b,&iso(3001)).unwrap();assert_eq!(result.source_sequence,1);assert_eq!(result.report["cash"],"50000.000000");assert_eq!(f.bank.engine().wallet.initial,50_000_000_000);assert_eq!(result.report["realized"],before["realized"]);assert_eq!(result.report["reservedCash"],before["reservedCash"]);assert_eq!(orders,f.bank.engine().order_records());assert_eq!(authority::reconciled_expected_cash(&f.bank).unwrap(),expected);assert_eq!(fs::read(f.root.join("bank/manifest.json")).unwrap(),manifest);let blank=Session::open_live(&f.root.join("blank"),&f.policy,&f.seed).unwrap();drop(std::mem::replace(&mut f.bank,blank));f.bank=Session::open_live(&f.root.join("bank"),&f.policy,&f.seed).unwrap();assert_eq!(f.bank.engine().report().unwrap(),result.report);assert_eq!(f.bank.durable_head(),result.durable_head);}
#[test]fn unrelated_unknown_and_original_unresolved_attempt_block_allocation(){for unknown in [false,true]{let mut f=F::with_unknown(unknown);if !unknown{let q=f.bank.engine().order_records()[0]["id"].as_u64().unwrap();f.ordinary.append(json!({"kind":"intent","qid":q})).unwrap();f.ordinary.append(json!({"kind":"attempt","qid":q})).unwrap();}let a=f.sources();let mandate=f.mandate();let old=f.bank.durable_head();assert!(prepare(&f.bank,&boundary!(f),&mandate,sources(&a),&iso(3000)).is_err());assert_eq!(old,f.bank.durable_head());}}
#[test]fn source_mutation_or_native_head_change_between_prepare_and_commit_fail_closed(){for case in ["source","native","journal","time"]{let mut f=F::new();let a=f.sources();let mandate=f.mandate();let b=boundary!(f);let tx=prepare(&f.bank,&b,&mandate,sources(&a),&iso(3000)).unwrap();match case{"source"=>{let receipt=a[0].receipt();let path=f.root.join("receipts").join(format!("{}.json",feedback::digest(receipt).unwrap()));let raw=fs::read_to_string(&path).unwrap().replace("70850.43","70850.44");fs::write(path,raw).unwrap();},"native"=>{f.bank.accept("tick",1,&json!({"type":"tick","receivedAt":iso(3000)})).unwrap();},"journal"=>{let path=f.root.join("dispatch.ndjson");fs::rename(&path,f.root.join("dispatch.original")).unwrap();fs::write(path,"").unwrap();},_=>{}}let old=f.bank.durable_head();assert!(tx.commit(&mut f.bank,&b,&iso(if case=="time"{63001}else{3001})).is_err(),"{case}");assert_eq!(old,f.bank.durable_head());}}
#[test]fn incomplete_or_foreign_or_borrowed_snapshot_is_not_new_owner_cash(){for case in ["coverage","open","position","debt","advance","profile","cash","clock"]{let f=F::new();let a=f.sources();let mut r=a[match case{"coverage"|"open"=>3,"position"=>2,"debt"|"advance"=>1,_=>0}].receipt().clone();match case{"coverage"=>r.data["coverage"]["complete"]=json!(false),"open"=>r.data["data"]=json!([{"id":"999"}]),"position"=>r.data["positions"]=json!([{"exchangeId":"101","marketId":"101","quantity":1,"lots":[]}]),"debt"=>r.data["data"][0]["outstandingAdvance"]=json!(1),"advance"=>r.data["availableAdvance"]=json!(1),"profile"=>r.data["id"]=json!("other"),"cash"=>{r.data["balance"]=json!(70851);r.data["buyingPower"]=json!(70851);},_=>r.received_at=iso(3001)}let replacement=retain(&f.root,&r);let mut refs=[&a[0],&a[1],&a[2],&a[3]];refs[match case{"coverage"|"open"=>3,"position"=>2,"debt"|"advance"=>1,_=>0}]=&replacement;let ss=Sources{account:refs[0],collateral:refs[1],positions:refs[2],orders:refs[3]};assert!(prepare(&f.bank,&boundary!(f),&f.mandate(),ss,&iso(3000)).is_err(),"{case}");}}
#[test]fn mandate_requires_exact_pinned_approval_not_self_declared_control(){let f=F::new();let input=MandateInput{authorization_id:"human_moloch_additional_cash_20261016".into(),allocation_id:"x".into(),control_sha256:"b".repeat(64),bank_manifest_hash:f.bank.manifest_hash().as_str().unwrap().into(),run_id:"capital-fixture".into(),account_scope:"fixture-account".into(),tournament_id:T.into(),tournament_slug:"cup".into(),profile_id:P.into(),scope_sha256:hash(&f.transport.scope()),delta:"10000.000000".into(),maximum_extra:"55579.915000".into(),maximum_effective_initial:"95579.915000".into(),maximum_committed:"95579.915000".into(),approved_at:iso(0),valid_until:iso(20000)};assert!(ApprovedMandate::verify(input,&"a".repeat(64)).is_err());}
#[cfg(target_os="linux")]
#[test]fn only_hydrated_original_sdk_abort_with_native_retirement_can_cross_allocation_boundary(){
 use baal_transport_service::{RequestSpec,Permit,TransportError};
 let mut f=F::new();let q=f.bank.engine().order_records().into_iter().find(|q|q["side"]=="YES").unwrap();let qid=q["id"].as_u64().unwrap();let n=q["quantity"].as_u64().unwrap();let at=chrono::DateTime::parse_from_rfc3339(&iso(2750)).unwrap().timestamp_millis()as u64;
 let body=json!({"tournamentId":T,"exchangeId":q["exchangeId"],"side":"yes","action":"buy","quantity":n,"price":0.4,"idempotencyKey":"capital-fixture:failed","expirationDate":iso(10000)});let spec=RequestSpec{method:"POST".into(),endpoint:"/orders".into(),body_json:Some(body.to_string()),body:Some(body)};let permit=Permit{run_id:"capital-fixture".into(),intent_id:qid.to_string(),owner:"Codex".into(),expires_at_ms:at-1,maximum_quantity:n as u32,maximum_cost:moloch_replay::money(400000*n as i128)};let error=TransportError{code:"PERMIT_EXPIRED_OR_INVALID".into(),status:None,may_have_executed:false,retry_after_ms:0,order_id:None,api_code:None};
 for e in [json!({"kind":"intent","qid":qid,"quote":q,"spec":spec,"permit":permit}),json!({"kind":"attempt","qid":qid,"at":iso(2750),"captureAtMs":at}),json!({"kind":"error","qid":qid,"at":iso(2751),"error":error})]{f.ordinary.append(e).unwrap();}
 let proof=f.transport.verify_current_ordinary_pre_admission(&spec,&permit,at,&error).unwrap();f.ordinary.append_aborted_before_admission(qid,&proof,&iso(2752)).unwrap();let a=f.sources();let mandate=f.mandate();assert!(prepare(&f.bank,&boundary!(f),&mandate,sources(&a),&iso(3000)).is_err(),"proof alone cannot abandon native reservation");
 f.bank.accept("no-network",1,&json!({"type":"unsubmitted_intent_retired","source":"moloch_live_dispatcher","receivedAt":iso(2753),"processedAt":iso(2753),"orderId":qid,"confirmedNetworkAttempts":0,"receiptHash":hash(proof.evidence()),"deferPlanningForPackage":true})).unwrap();
 let replacement=dispatch::DispatchLog::open(&f.root.join("replacement.ndjson")).unwrap();drop(std::mem::replace(&mut f.ordinary,replacement));f.ordinary=dispatch::DispatchLog::open(&f.root.join("dispatch.ndjson")).unwrap();assert!(!f.ordinary.proved_no_network(qid));assert!(prepare(&f.bank,&boundary!(f),&mandate,sources(&a),&iso(3000)).is_err(),"serialized proof is not an opaque SDK verification");
 f.ordinary.verify_aborted_before_admission(qid,&proof).unwrap();let b=boundary!(f);prepare(&f.bank,&b,&mandate,sources(&a),&iso(3000)).unwrap().commit(&mut f.bank,&b,&iso(3001)).unwrap();assert!(f.ordinary.attempted.contains(&qid)&&!f.ordinary.closed.contains(&qid)&&!f.ordinary.never_attempted(qid)&&f.ordinary.acknowledgments.is_empty());
}


#[cfg(target_os="linux")]
#[test]fn only_opaque_final_guard_proof_and_zero_fill_native_retirement_cross_allocation_boundary(){
 use baal_transport_service::{Authority,Clock,Order,Permit,RequestSpec,TransportError};
 use std::{os::unix::fs::PermissionsExt,sync::{Arc,atomic::{AtomicU64,Ordering}}};
 struct FixedClock(Arc<AtomicU64>);
 impl Clock for FixedClock{fn now_ms(&self)->u64{self.0.load(Ordering::SeqCst)}fn sleep_ms(&mut self,n:u64)->baal_transport_service::Result<()>{self.0.fetch_add(n,Ordering::SeqCst);Ok(())}}
 struct FinalGuard(AtomicU64);
 impl Authority for FinalGuard{
  fn can_read(&self,_:&Scope)->bool{true}fn owns_order(&self,_:&str)->bool{false}
  fn authorize(&self,_:&Scope,_:&RequestSpec,_:&Permit,network:bool,_:u64)->baal_transport_service::Result<()>{if network&&self.0.fetch_add(1,Ordering::SeqCst)>0{Err(TransportError{code:"LIVE_CONTRACT_OR_BOOK_STALE".into(),status:None,may_have_executed:false,retry_after_ms:0,order_id:None,api_code:None})}else{Ok(())}}
 }
 let mut f=F::new();let q=f.bank.engine().order_records().into_iter().find(|q|q["side"]=="YES").unwrap();let qid=q["id"].as_u64().unwrap();let n=q["quantity"].as_u64().unwrap();let at=chrono::DateTime::parse_from_rfc3339(&iso(2750)).unwrap().timestamp_millis()as u64;
 // Synthetic fixture credentials never leave this private temporary directory.
 let dir=f.root.join("synthetic-credentials");fs::create_dir(&dir).unwrap();fs::set_permissions(&dir,fs::Permissions::from_mode(0o700)).unwrap();let file=dir.join("synthetic");fs::write(&file,b"ace_synthetic_fixture_only_00000000").unwrap();fs::set_permissions(&file,fs::Permissions::from_mode(0o600)).unwrap();
 let scope=f.transport.scope().clone();let replacement=Transport::new_for_mock(Config{queue_dir:f.root.join("replacement-queue"),account_scope:"replacement".into(),scope:scope.clone(),maximum_pages:20,writes_enabled:false},Box::new(DisabledCredentials),Box::new(SystemClock),Box::new(ReadOnlyAuthority),"http://127.0.0.1:1/api/v1".into()).unwrap();drop(std::mem::replace(&mut f.transport,replacement));
 let listener=std::net::TcpListener::bind("127.0.0.1:0").unwrap();listener.set_nonblocking(true).unwrap();f.transport=Transport::new_for_mock(Config{queue_dir:f.root.join("account-queue"),account_scope:"fixture-account".into(),scope,maximum_pages:20,writes_enabled:true},Box::new(baal_transport_service::credentials::UnixFileCredentials::approved_file(file).unwrap()),Box::new(FixedClock(Arc::new(AtomicU64::new(at)))),Box::new(FinalGuard(AtomicU64::new(0))),format!("http://{}/api/v1",listener.local_addr().unwrap())).unwrap();
 let order=Order{idempotency_key:format!("capital-fixture:{qid}"),exchange_id:q["exchangeId"].as_str().unwrap().into(),side:"yes".into(),action:"buy".into(),quantity:n as u32,price:"0.400000".into(),expiration_date:iso(10000),tournament_id:T.into()};
 let body=json!({"idempotencyKey":order.idempotency_key,"exchangeId":order.exchange_id,"side":order.side,"action":order.action,"quantity":order.quantity,"price":serde_json::Number::from_string_unchecked(order.price.clone()),"expirationDate":order.expiration_date,"tournamentId":order.tournament_id});let spec=RequestSpec{method:"POST".into(),endpoint:"/orders".into(),body_json:Some(body.to_string()),body:Some(body)};
 let permit=Permit{run_id:"capital-fixture".into(),intent_id:qid.to_string(),owner:"Codex".into(),expires_at_ms:at+10000,maximum_quantity:n as u32,maximum_cost:moloch_replay::money(400000*n as i128)};
 for e in [json!({"kind":"intent","qid":qid,"quote":q,"spec":spec,"permit":permit}),json!({"kind":"attempt","qid":qid,"at":iso(2750),"captureAtMs":at})]{f.ordinary.append(e).unwrap();}
 let error=f.transport.place(order,permit.clone()).err().expect("final guard must reject before HTTP");assert_eq!(error.code,"LIVE_CONTRACT_OR_BOOK_STALE");assert!(!error.may_have_executed);assert_eq!(listener.accept().unwrap_err().kind(),std::io::ErrorKind::WouldBlock);f.ordinary.append(json!({"kind":"error","qid":qid,"at":iso(2751),"error":error})).unwrap();
 let proof=f.transport.take_current_ordinary_local_guard_no_http_proof(&spec,&permit,at,&error).unwrap();f.ordinary.append_local_final_guard_no_http(qid,&proof,&iso(2752)).unwrap();assert!(f.ordinary.aborted_records().is_empty());assert_eq!(f.ordinary.local_final_guard_records().len(),1);
 let a=f.sources();let mandate=f.mandate();assert!(prepare(&f.bank,&boundary!(f),&mandate,sources(&a),&iso(3000)).is_err(),"no-network proof does not itself retire native reservation");
 f.bank.accept("no-network",1,&json!({"type":"unsubmitted_intent_retired","source":"moloch_live_dispatcher","receivedAt":iso(2753),"processedAt":iso(2753),"orderId":qid,"confirmedNetworkAttempts":0,"receiptHash":hash(&proof.evidence().unwrap()),"deferPlanningForPackage":true})).unwrap();
 assert!(collateral_feedback::prepare(&f.bank,&boundary!(f),collateral_feedback::Operation::Baseline{after:collateral_feedback::Snapshot{account:&a[0],collateral:&a[1]}},&iso(3000)).is_err(),"ordinary collateral boundary remains strict");
 let replacement=dispatch::DispatchLog::open(&f.root.join("replacement.ndjson")).unwrap();drop(std::mem::replace(&mut f.ordinary,replacement));f.ordinary=dispatch::DispatchLog::open(&f.root.join("dispatch.ndjson")).unwrap();assert!(!f.ordinary.proved_no_network(qid));assert!(prepare(&f.bank,&boundary!(f),&mandate,sources(&a),&iso(3000)).is_err(),"serialized local-guard record cannot hydrate opaque authority");
 f.ordinary.verify_local_final_guard_no_http(qid,&proof).unwrap();let b=boundary!(f);let captured=collateral_feedback::allocation_boundary(&f.bank,&b,chrono::DateTime::parse_from_rfc3339(&iso(3000)).unwrap().timestamp_millis()).unwrap();assert_eq!(captured["provedNoNetworkOrderIds"],json!([qid]));prepare(&f.bank,&b,&mandate,sources(&a),&iso(3000)).unwrap().commit(&mut f.bank,&b,&iso(3001)).unwrap();assert!(f.ordinary.attempted.contains(&qid)&&!f.ordinary.closed.contains(&qid)&&!f.ordinary.never_attempted(qid)&&f.ordinary.acknowledgments.is_empty());
}

