 let anchor=chrono::DateTime::parse_from_rfc3339(&iso(100000)).unwrap().timestamp_millis();let old=json!({"authorizationId":"human-original40k","approvedAt":iso(0),"anchorMs":anchor,"campaignEndMs":anchor+20*86400000i64,"intervalMs":86400000,"maximumCommitted":"40000.000000","maximumMarketCost":"10000.000000","maximumQuantity":2});
